using UnityEngine;
using UnityEngine.InputSystem;
namespace FarmPrototype.Player
{
 public sealed class FarmEquipmentController : MonoBehaviour
 {
  [SerializeField] GameObject hoe; [SerializeField] GameObject seeds; [SerializeField] GameObject wateringCan;
  void Start(){ Select(hoe); var hand=Find(transform,"Prop_R_Socket") ?? Find(transform,"Hand_R"); if(hand==null) return; Attach(hoe,hand,new Vector3(.04f,0,0),new Vector3(10,90,80)); Attach(seeds,hand,Vector3.zero,new Vector3(0,90,0)); Attach(wateringCan,hand,new Vector3(.03f,0,0),new Vector3(0,90,70)); }
  void Update(){var k=Keyboard.current;if(k==null)return;if(k.digit1Key.wasPressedThisFrame)Select(hoe);if(k.digit2Key.wasPressedThisFrame)Select(seeds);if(k.digit3Key.wasPressedThisFrame)Select(wateringCan);if(k.digit4Key.wasPressedThisFrame)Select(null);}
  void Select(GameObject x){if(hoe)hoe.SetActive(x==hoe);if(seeds)seeds.SetActive(x==seeds);if(wateringCan)wateringCan.SetActive(x==wateringCan);}
  static void Attach(GameObject x,Transform t,Vector3 p,Vector3 r){if(!x)return;x.transform.SetParent(t,false);x.transform.localPosition=p;x.transform.localRotation=Quaternion.Euler(r);}
  static Transform Find(Transform r,string n){foreach(var x in r.GetComponentsInChildren<Transform>(true))if(x.name==n)return x;return null;}
 }
}
